"""Cart pricing."""

from cart.models import Line, Totals

_BULK_MIN_QTY = 10
_BULK_PERCENT = 10


def _percent_of(amount: int, percent: int) -> int:
    """`percent` of `amount` in whole cents, halves rounding up."""
    return (amount * percent + 50) // 100


def _parse_coupon(coupon: str) -> tuple[str, int]:
    """Split a coupon into its kind ("PERCENT"/"FIXED") and numeric value."""
    for kind in ("PERCENT", "FIXED"):
        if coupon.startswith(kind + ":"):
            digits = coupon[len(kind) + 1 :]
            if digits.isdigit():
                return kind, int(digits)
            break
    raise ValueError(f"invalid coupon: {coupon!r}")


def price_cart(lines: list[Line], coupon: str | None = None) -> Totals:
    """Price a cart. See README.md for the discount rules."""
    for line in lines:
        if line.qty < 1:
            raise ValueError(f"quantity must be at least 1 for sku {line.sku!r}")
        if line.unit_cents < 0:
            raise ValueError(f"unit price must not be negative for sku {line.sku!r}")

    subtotal = sum(line.unit_cents * line.qty for line in lines)

    bulk_discount = sum(
        _percent_of(line.unit_cents * line.qty, _BULK_PERCENT)
        for line in lines
        if line.qty >= _BULK_MIN_QTY
    )
    remaining = subtotal - bulk_discount

    coupon_discount = 0
    if coupon is not None:
        kind, value = _parse_coupon(coupon)
        if kind == "PERCENT":
            if not 1 <= value <= 100:
                raise ValueError(f"percentage must be between 1 and 100: {coupon!r}")
            coupon_discount = _percent_of(remaining, value)
        else:
            coupon_discount = min(value, remaining)

    discount = bulk_discount + coupon_discount
    return Totals(subtotal, discount, subtotal - discount)
